{"version":3,"file":"ProjectNeeds-BzvYrWAY.js","names":[],"sources":["../../src/features/needs/ProjectNeeds.tsx"],"sourcesContent":["import { getRouteApi } from \"@tanstack/react-router\";\nimport { NeedCard, rankNeeds } from \"@/components/needs/NeedCard\";\nimport { useRovingNeedFocus } from \"@/features/inbox/GlobalInbox\";\nimport { QueryBoundary } from \"@/components/ui/states\";\nimport { Kbd } from \"@/components/ui/primitives\";\nimport { useNeeds, useProjects } from \"@/lib/queries\";\n\nconst route = getRouteApi(\"/p/$projectId/needs\");\n\n/** Project-scoped needs-me queue. Same cards as the global inbox, filtered. */\nexport function ProjectNeeds() {\n  const { projectId } = route.useParams();\n  const needsQ = useNeeds(projectId);\n  const projects = useProjects();\n  const projectName = projects.data?.find((p) => p.id === projectId)?.name ?? projectId;\n  const listRef = useRovingNeedFocus();\n\n  return (\n    <div className=\"tk-scroll h-full overflow-y-auto\">\n      <div className=\"mx-auto w-full max-w-[900px] px-4 pb-20 pt-[30px] sm:px-11\">\n        <div className=\"mb-1.5 font-mono text-[11px] text-faint\">◇ {projectName}</div>\n        <h1 className=\"font-serif text-[30px] font-semibold tracking-[-0.02em] text-ink\">Needs me</h1>\n        <p className=\"mb-5 mt-1.5 flex items-center gap-1.5 font-mono text-[11px] text-fainter\">\n          <Kbd>J</Kbd> jump to next · <Kbd>K</Kbd> previous\n        </p>\n\n        <QueryBoundary q={needsQ}>\n          {(needs) =>\n            needs.length === 0 ? (\n              <div className=\"rounded-xl border border-line bg-panel p-12 text-center text-[14px] text-muted\">\n                Nothing needs you on this project.\n              </div>\n            ) : (\n              <div ref={listRef} className=\"border-t border-line-soft\">\n                {rankNeeds(needs).map((need) => (\n                  <NeedCard key={need.id} need={need} />\n                ))}\n              </div>\n            )\n          }\n        </QueryBoundary>\n      </div>\n    </div>\n  );\n}\n"],"mappings":"4QAOM,EAAQ,EAAY,qBAAqB,EAG/C,SAAgB,GAAe,CAC7B,GAAM,CAAE,aAAc,EAAM,UAAU,EAChC,EAAS,EAAS,CAAS,EAE3B,EADW,EACG,CAAA,CAAS,MAAM,KAAM,GAAM,EAAE,KAAO,CAAS,CAAC,EAAE,MAAQ,EACtE,EAAU,EAAmB,EAEnC,OACE,EAAA,EAAA,IAAA,CAAC,MAAD,CAAK,UAAU,6CACb,EAAA,EAAA,KAAA,CAAC,MAAD,CAAK,UAAU,sEAAf,EACE,EAAA,EAAA,KAAA,CAAC,MAAD,CAAK,UAAU,mDAAf,CAAyD,KAAG,CAAiB,KAC7E,EAAA,EAAA,IAAA,CAAC,KAAD,CAAI,UAAU,4EAAmE,UAAY,CAAA,GAC7F,EAAA,EAAA,KAAA,CAAC,IAAD,CAAG,UAAU,oFAAb,EACE,EAAA,EAAA,IAAA,CAAC,EAAD,CAAA,SAAK,GAAM,CAAA,EAAC,oBAAgB,EAAA,EAAA,IAAA,CAAC,EAAD,CAAA,SAAK,GAAM,CAAA,EAAC,WACvC,KAEH,EAAA,EAAA,IAAA,CAAC,EAAD,CAAe,EAAG,WACd,GACA,EAAM,SAAW,GACf,EAAA,EAAA,IAAA,CAAC,MAAD,CAAK,UAAU,0FAAiF,oCAE3F,CAAA,GAEL,EAAA,EAAA,IAAA,CAAC,MAAD,CAAK,IAAK,EAAS,UAAU,qCAC1B,EAAU,CAAK,CAAC,CAAC,IAAK,IACrB,EAAA,EAAA,IAAA,CAAC,EAAD,CAA8B,MAAO,EAAtB,EAAK,EAAiB,CACtC,CACE,CAAA,CAGI,CAAA,CACZ,GACF,CAAA,CAET"}
